using System.Text;
using System.Text.Json;
var temp=Path.Combine(Path.GetTempPath(),"LibraryPreparation-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
var count=0;void Check(bool yes,string name){if(!yes)throw new Exception(name);Console.WriteLine("PASS "+name);count++;}
async Task Reject(Func<Task> action,string name){try{await action();}catch(Exception e)when(e is LibraryBomPermissionException or SimRfqIntakeProblem or IOException){Check(true,name);return;}throw new Exception("Did not reject: "+name);}
JsonElement J(object o)=>JsonSerializer.SerializeToElement(o,SimLibraryBomStore.Json);string Token(object o)=>J(o).GetProperty("token").GetString()!;
LibraryPreparation Record(object o)=>J(o).GetProperty("record").Deserialize<LibraryPreparation>(SimLibraryBomStore.Json)!;
SimPersona P(params string[] rights)=>new("fixture","fixture","Fixture","ACTIVE",[],rights,false,"test");
var tr=P("technical_review.view","technical_review.disposition");var reader=P("technical_review.view");var editor=P("assembly_library.view","assembly_library.edit");var viewer=P("assembly_library.view");var both=P("assembly_library.view","assembly_library.edit","technical_review.view","technical_review.disposition");
var h=new SimAssemblyHeader(" A ","fixture","V1.2","A","D","R","ABC","R",true);var headers=new[]{h,h with{SourceKeyRaw="A "}};
var bytes=Encoding.UTF8.GetBytes("immutable intake fixture");var original=bytes.ToArray();var doc=new SimRfqIntakeDocument("incoming.txt",bytes.Length,"text/plain",0,"doc-1","VERIFIED");
var incoming=new PreparationIntake("request-1","correlation-1",new("customer-1","001","Fixture customer","fixture"),[new(1,"NEW","A",10),new(2,"NEW","B",20)],[doc],"TECHNICAL_REVIEW_PENDING");
Task<PreparationIntake> Source(string id)=>Task.FromResult(incoming with{IntakeId=id});bool missing=false;
Task<(SimRfqIntakeDocument Document,byte[] Bytes)> Open(string id,string docId){if(missing)throw new IOException("missing fixture");return Task.FromResult((doc,bytes));}
SimLibraryPreparation Store()=>new(temp,()=>headers,Source,Open);var store=Store();
PreparationCommand Cmd(object view,string action="SEND",string? key=null)=>new(Record(view).IntakeId,Record(view).LineNumber,Token(view),J(view).GetProperty("sourceFingerprint").GetString()!,action,key,key is null?"A":"R",key is null?"A":"R","Prepare BOM and identify drawing",["doc-1"]);
var view=await store.Assessment("request-1",1,tr);Check(!Directory.Exists(Path.Combine(temp,"library-preparation-v1")),"assessment read creates no data");
Check(J(view).GetProperty("headers").GetArrayLength()==0,"TR-only does not expose Library headers");
await Reject(()=>store.Assess(Cmd(view),reader),"TR viewer cannot route");await Reject(()=>store.Assessment("request-1",1,editor),"Library edit does not grant TR access");await Reject(()=>store.Queue(tr),"TR rights do not grant Library view");await Reject(()=>store.Assessment("request-1",9,tr),"missing assembly line rejected");
await Reject(()=>store.Assess(Cmd(view) with{Work=""},tr),"routing requires preparation work");await Reject(()=>store.Assess(Cmd(view) with{DocumentIds=["not-intake-file"]},tr),"foreign file denied");await Reject(()=>store.Assess(Cmd(view) with{DocumentIds=["doc-1","doc-1"]},tr),"duplicate files denied");await Reject(()=>store.Assess(Cmd(view,key:h.SourceKeyRaw),tr),"existing Library match requires Library view");
view=await store.Assess(Cmd(view,"SAVE") with{Work="",DocumentIds=[]},tr);Check(Record(view).Status=="ASSESSMENT_DRAFT","incomplete assessment can save");
view=await store.Assess(Cmd(view,"REQUEST_INFORMATION") with{Work="Need revision"},tr);Check(Record(view).Status=="WAITING_FOR_INFORMATION"&&J(await store.Queue(viewer)).GetProperty("items").GetArrayLength()==0,"information hold does not route to Library");
var stale=Cmd(view);view=await store.Assess(Cmd(view),tr);var routed=Record(view);Check(routed.Status=="NEEDS_PREPARATION"&&routed.Files.Single().Sha256==SimLibraryBomStore.Hash(original),"routing freezes selected original hash");
Check(routed.History.Last().Files!.Length==1&&routed.History.Last().SourceFingerprint==routed.SourceFingerprint,"assessment history preserves file and source context");
await Reject(()=>store.Assess(stale,tr),"stale reviewer save rejected");var repeated=await store.Assess(Cmd(view),tr);Check(Token(view)==Token(repeated),"repeated route idempotent");
Check(J(await store.Queue(viewer)).GetProperty("items").GetArrayLength()==1,"single queue item after repeated route");
await Reject(()=>store.Work(new(routed.Id,Token(view),"START"),viewer),"Library viewer cannot start");
incoming=incoming with{Status="CHANGED"};await Reject(()=>store.Work(new(routed.Id,Token(view),"START"),editor),"changed intake requires reassessment before start");incoming=incoming with{Status="TECHNICAL_REVIEW_PENDING"};
var started=await store.Work(new(routed.Id,Token(view),"START"),editor);var r=Record(started);Check(r.Status=="IN_PREPARATION"&&r.LibraryKey!.StartsWith("LIBRARY:"),"new assembly independent of BMM snapshot");
Check(store.Headers().Length==3&&store.Headers().Single(x=>x.SourceKeyRaw==r.LibraryKey).BomRevision=="A","managed identity and explicit revision persisted");
Check(Token(started)==Token(await store.Work(new(r.Id,Token(started),"START"),editor)),"repeated start does not duplicate identity");
await Reject(async()=>await store.Assess(Cmd(await store.Assessment("request-1",1,tr)),tr),"started preparation protected from silent rerouting");
Check(J(await store.Evidence(r.Id,"doc-1",viewer)).GetProperty("base64").GetString()==Convert.ToBase64String(original),"Library viewer can read only routed verified evidence");
await Reject(()=>store.Evidence(r.Id,"foreign",viewer),"foreign evidence denied");await Reject(()=>store.Work(new("../invalid",Token(started),"START"),editor),"unsafe preparation identity denied");
bytes=Encoding.UTF8.GetBytes("changed");await Reject(()=>store.Work(new(r.Id,Token(started),"PROMOTE","doc-1"),editor),"changed source rejects promotion");Check(Record(started).Promoted.Length==0,"failed promotion leaves previous reference intact");
var afterFail=J(await store.Queue(viewer)).GetProperty("items")[0];Check(afterFail.GetProperty("token").GetString()==Token(started),"failed promotion saves no record changes");
bytes=original;missing=true;await Reject(()=>store.Work(new(r.Id,Token(started),"PROMOTE","doc-1"),editor),"missing source rejects promotion");missing=false;
var evidencePath=Path.Combine(temp,"library-preparation-v1","evidence");await File.WriteAllTextAsync(evidencePath,"fixture obstruction");await Reject(()=>store.Work(new(r.Id,Token(started),"PROMOTE","doc-1"),editor),"copy write failure does not promote");Check(J(await store.Queue(viewer)).GetProperty("items")[0].GetProperty("token").GetString()==Token(started),"copy write failure preserves queue token");File.Delete(evidencePath);
var promoted=await store.Work(new(r.Id,Token(started),"PROMOTE","doc-1"),editor);Check(Record(promoted).Promoted.SequenceEqual(new[]{"doc-1"}),"explicit promotion saves verified Library copy");Check(bytes.SequenceEqual(original),"original bytes untouched");
Check(Token(promoted)==Token(await store.Work(new(r.Id,Token(promoted),"PROMOTE","doc-1"),editor)),"promotion retry idempotent");
missing=true;Check(J(await Store().Evidence(r.Id,"doc-1",viewer)).GetProperty("base64").GetString()==Convert.ToBase64String(original),"promoted evidence survives original loss and store reopen");missing=false;
var reopened=await Store().Assessment("request-1",1,tr);Check(Token(reopened)==Token(promoted),"assessment store reload preserves state and history");
var second=await store.Assessment("request-2",1,both);second=await store.Assess(Cmd(second,key:h.SourceKeyRaw),both);var existing=await store.Work(new(Record(second).Id,Token(second),"START"),editor);Check(Record(existing).LibraryKey==" A ","exact whitespace-sensitive existing Library key preserved");Check(store.Headers().Length==3,"existing handoff creates no duplicate assembly");
var rev=await store.Assessment("request-1",2,tr);rev=await store.Assess(Cmd(rev) with{DrawingRevision="B",BomRevision="B",DocumentIds=[]},tr);var revStart=await store.Work(new(Record(rev).Id,Token(rev),"START"),editor);Check(Record(revStart).LibraryKey!=r.LibraryKey&&Record(revStart).IncomingRevision=="B","assembly lines and revision contexts distinct");
Check((await new SimLibraryBomStore(temp,store.Headers).Get(r.LibraryKey!,viewer)).Record.Draft is null,"new Library identity usable without creating BOM");
Check(!Directory.Exists(Path.Combine(temp,"data"))&&!Directory.Exists(Path.Combine(temp,"assembly-library-v1")),"no job, BOM, folder or approval store mutations");
await Reject(async()=>await store.Assess(Cmd(await store.Assessment("request-3",1,tr)) with{LibraryKey="missing"},both),"unknown Library key rejected");
var ended=await store.Assessment("ended",1,tr);incoming=incoming with{Status="READY_FOR_RFQ_WORKING_QUEUE"};await Reject(()=>store.Assess(Cmd(ended),tr),"completed RFQ cannot be routed");
Console.WriteLine($"TOTAL {count} checks passed. Isolated fixture: {temp}");
